import os
from typing import Any, Dict, List, Optional, Union

import boto3


def extract_document_layout(
    file_path: Optional[str] = None,
    file_bytes: Optional[bytes] = None,
    features: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or "us-east-1")

    if (file_path is None and file_bytes is None) or (file_path is not None and file_bytes is not None):
        raise ValueError("Provide exactly one of file_path or file_bytes")

    if file_bytes is None:
        with open(file_path, "rb") as f:
            file_bytes = f.read()

    feature_types = features or ["TABLES", "FORMS", "LAYOUT"]

    response = textract.analyze_document(
        Document={"Bytes": file_bytes},
        FeatureTypes=feature_types,
    )

    blocks = response.get("Blocks", [])
    block_map = {block["Id"]: block for block in blocks if "Id" in block}

    def child_ids(block: Dict[str, Any], relationship_type: str = "CHILD") -> List[str]:
        ids: List[str] = []
        for rel in block.get("Relationships", []):
            if rel.get("Type") == relationship_type:
                ids.extend(rel.get("Ids", []))
        return ids

    def block_text(block: Dict[str, Any]) -> str:
        if block.get("BlockType") in {"WORD", "LINE"}:
            return block.get("Text", "")
        parts: List[str] = []
        for cid in child_ids(block):
            child = block_map.get(cid)
            if not child:
                continue
            if child.get("BlockType") == "WORD":
                parts.append(child.get("Text", ""))
            elif child.get("BlockType") == "SELECTION_ELEMENT" and child.get("SelectionStatus") == "SELECTED":
                parts.append("X")
        return " ".join(p for p in parts if p).strip()

    def polygon(block: Dict[str, Any]) -> List[Dict[str, float]]:
        return block.get("Geometry", {}).get("Polygon", [])

    def bbox(block: Dict[str, Any]) -> Dict[str, float]:
        return block.get("Geometry", {}).get("BoundingBox", {}) or {}

    lines: List[Dict[str, Any]] = []
    words: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []
    key_values: List[Dict[str, Any]] = []
    layout_elements: List[Dict[str, Any]] = []

    key_blocks: Dict[str, Dict[str, Any]] = {}
    value_blocks: Dict[str, Dict[str, Any]] = {}

    for block in blocks:
        block_type = block.get("BlockType")

        if block_type == "LINE":
            lines.append(
                {
                    "id": block.get("Id"),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "page": block.get("Page"),
                    "bounding_box": bbox(block),
                    "polygon": polygon(block),
                }
            )
        elif block_type == "WORD":
            words.append(
                {
                    "id": block.get("Id"),
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "page": block.get("Page"),
                    "bounding_box": bbox(block),
                    "polygon": polygon(block),
                }
            )
        elif block_type == "KEY_VALUE_SET":
            entity_types = set(block.get("EntityTypes", []))
            if "KEY" in entity_types:
                key_blocks[block["Id"]] = block
            if "VALUE" in entity_types:
                value_blocks[block["Id"]] = block
        elif block_type and block_type.startswith("LAYOUT_"):
            layout_elements.append(
                {
                    "id": block.get("Id"),
                    "type": block_type,
                    "text": block_text(block),
                    "confidence": block.get("Confidence"),
                    "page": block.get("Page"),
                    "bounding_box": bbox(block),
                    "polygon": polygon(block),
                }
            )

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        cells: List[Dict[str, Any]] = []
        max_row = 0
        max_col = 0

        for cid in child_ids(block):
            cell = block_map.get(cid)
            if not cell or cell.get("BlockType") != "CELL":
                continue

            row_index = cell.get("RowIndex", 1)
            col_index = cell.get("ColumnIndex", 1)
            row_span = cell.get("RowSpan", 1)
            col_span = cell.get("ColumnSpan", 1)
            max_row = max(max_row, row_index + row_span - 1)
            max_col = max(max_col, col_index + col_span - 1)

            cells.append(
                {
                    "id": cell.get("Id"),
                    "row_index": row_index,
                    "column_index": col_index,
                    "row_span": row_span,
                    "column_span": col_span,
                    "text": block_text(cell),
                    "confidence": cell.get("Confidence"),
                    "page": cell.get("Page"),
                    "bounding_box": bbox(cell),
                    "polygon": polygon(cell),
                }
            )

        grid = [["" for _ in range(max_col)] for _ in range(max_row)]
        for cell in cells:
            r = cell["row_index"] - 1
            c = cell["column_index"] - 1
            if 0 <= r < max_row and 0 <= c < max_col:
                grid[r][c] = cell["text"]

        tables.append(
            {
                "id": block.get("Id"),
                "page": block.get("Page"),
                "confidence": block.get("Confidence"),
                "bounding_box": bbox(block),
                "polygon": polygon(block),
                "n_rows": max_row,
                "n_columns": max_col,
                "cells": cells,
                "grid": grid,
            }
        )

    for key_id, key_block in key_blocks.items():
        key_text = block_text(key_block)
        value_texts: List[str] = []
        value_ids = []
        for rel in key_block.get("Relationships", []):
            if rel.get("Type") == "VALUE":
                value_ids.extend(rel.get("Ids", []))

        for vid in value_ids:
            value_block = value_blocks.get(vid)
            if value_block:
                text = block_text(value_block)
                if text:
                    value_texts.append(text)

        key_values.append(
            {
                "id": key_id,
                "key": key_text,
                "value": " ".join(value_texts).strip(),
                "page": key_block.get("Page"),
                "confidence": key_block.get("Confidence"),
                "bounding_box": bbox(key_block),
                "polygon": polygon(key_block),
            }
        )

    return {
        "provider": "amazon-textract",
        "feature_types": feature_types,
        "document_metadata": response.get("DocumentMetadata", {}),
        "blocks": blocks,
        "lines": lines,
        "words": words,
        "tables": tables,
        "key_values": key_values,
        "layout_elements": layout_elements,
    }
